ID_CHARS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-'
COMMAND_TYPES = ('ha/switch', 'ha/number', 'ha/select')  # two-faced: an unwired input means echo (SPEC §3)

SENSOR_UNITS = {
    'temperature': ('°C', '°F', 'K'),
    'humidity': ('%',),
    'battery': ('%',),
    'pressure': ('Pa', 'hPa', 'kPa', 'bar', 'mbar', 'mmHg', 'inHg', 'psi'),
    'illuminance': ('lx',),
    'voltage': ('V', 'mV'),
    'current': ('A', 'mA'),
    'power': ('W', 'kW'),
    'energy': ('Wh', 'kWh', 'MWh'),
    'signal_strength': ('dB', 'dBm'),
    'duration': ('d', 'h', 'min', 's', 'ms'),
}


def label(node_type):
    """'ha/binary_sensor' -> 'ha binary sensor', as the palette shows it."""
    return 'ha ' + node_type[3:].replace('_', ' ')


def ha_devices(ctx):
    return [n for n in ctx['flow']['nodes'] if n['type'] == 'ha/device']


def _class(properties):
    value = properties.get('deviceClass') or ''
    return '' if value == 'none' else value


def _text(properties, key):
    return str(properties.get(key) or '').strip()


def _number(value):
    try:
        v = float(value)
    except (TypeError, ValueError):
        return None
    return int(v) if v == int(v) else v


def component(node_type, properties):
    """(the component dict SPEC §4 asks for, or None; the error, or None) for one entity node's properties. The
    entity's own hook reports the error; ha device's size check skips an entity that has one."""
    name = _text(properties, 'name')
    if not name:
        return None, '%s needs a name' % label(node_type)
    p = node_type[3:]
    comp = {'p': p, 'name': name}
    if p == 'sensor':
        dev_cla = _class(properties)
        unit = _text(properties, 'unit')
        if dev_cla:
            allowed = SENSOR_UNITS.get(dev_cla)
            if allowed and unit not in allowed:
                return None, 'ha sensor %r: a %s sensor\'s unit must be one of %s' % (name, dev_cla, ', '.join(allowed))
            comp['dev_cla'] = dev_cla
        if unit:
            comp['unit_of_meas'] = unit
        if properties.get('stateClass') not in (None, '', 'none'):
            comp['stat_cla'] = properties['stateClass']
        icon = _text(properties, 'icon')
        if icon:
            comp['ic'] = icon
    elif p in ('binary_sensor', 'switch'):
        if _class(properties):
            comp['dev_cla'] = _class(properties)
    elif p == 'number':
        values = {}
        for key in ('min', 'max', 'step'):
            values[key] = _number(properties.get(key))
            if values[key] is None:
                return None, 'ha number %r: %s must be a number' % (name, key)
        if values['min'] >= values['max']:
            return None, 'ha number %r: min must be below max' % name
        if values['step'] <= 0:
            return None, 'ha number %r: step must be above 0' % name
        comp.update(values)
        comp['mode'] = properties.get('mode') or 'slider'
        unit = _text(properties, 'unit')
        if unit:
            comp['unit_of_meas'] = unit
    elif p == 'select':
        ops = [line.strip() for line in str(properties.get('options') or '').split('\n') if line.strip()]
        if not ops:
            return None, 'ha select %r needs at least one option, one per line' % name
        for i, op in enumerate(ops):
            if op in ops[:i]:
                return None, 'ha select %r lists %r twice' % (name, op)
        comp['ops'] = ops
    elif p != 'button':
        return None, '%s is not an ha entity node' % node_type
    return comp, None


_ECHO_WHAT = {'ha/switch': ('each command', 'the real state'), 'ha/number': ('each change', 'the real value'),
              'ha/select': ('each choice', 'the current option')}


def entity_compile(ctx, node_type, properties):
    """The whole hook of an entity node: needs an ha device, builds its component, and for the two-faced nodes works
    out echo from whether the input is wired (SPEC §3)."""
    if not ha_devices(ctx):
        return {'errors': ['%s needs an ha device node in the flow' % label(node_type)]}
    comp, err = component(node_type, properties)
    if err:
        return {'errors': [err]}
    if node_type not in COMMAND_TYPES:
        return {'properties': {'component': comp}}
    wired = ((ctx.get('node') or {}).get('wired') or {}).get('inputs') or [False]
    echo = not wired[0]
    warnings = []
    if echo:
        what, real = _ECHO_WHAT[node_type]
        warnings.append('%s %r: input not wired, so HA shows %s as done -- wire %s back to the input to show what '
                        'actually happened' % (label(node_type), comp['name'], what, real))
    return {'properties': {'component': comp, 'echo': echo}, 'warnings': warnings}


def json_size(obj):
    """Bytes of `obj` as the board's json.dumps writes it with separators (',', ':'): UTF-8, no escaping beyond
    quotes, backslashes and control characters. Floats are counted as Python writes them; MicroPython's single
    precision floats can write a few characters fewer, never more."""
    if obj is None:
        return 4
    if obj is True:
        return 4
    if obj is False:
        return 5
    if isinstance(obj, (int, float)):
        return len(repr(obj))
    if isinstance(obj, str):
        n = 2
        for ch in obj:
            c = ord(ch)
            if ch in '"\\' or c in (8, 9, 10, 12, 13):
                n += 2
            elif c < 0x20:
                n += 6
            elif c < 0x80:
                n += 1
            elif c < 0x800:
                n += 2
            elif c < 0x10000:
                n += 3
            else:
                n += 4
        return n
    if isinstance(obj, (list, tuple)):
        return 2 + sum(json_size(v) for v in obj) + max(len(obj) - 1, 0)
    if isinstance(obj, dict):
        return 2 + sum(json_size(str(k)) + 1 + json_size(v) for k, v in obj.items()) + max(len(obj) - 1, 0)
    raise ValueError('json_size: can\'t size %r' % (obj,))


# -- from lib/ts_ha.py: BUNDLE_VERSION, COMMANDABLE, build_discovery --

BUNDLE_VERSION = "0.1.0"


COMMANDABLE = ("switch", "number", "select", "button")


def build_discovery(chip_id, prefix, device, components, record=None):
    """(topic, payload dict, record after) for SPEC §4/§7. `device` has name, model, runtime, area, bundle."""
    device_id = "ts_" + chip_id
    base = "thingstudio/" + chip_id
    dev = {"ids": [device_id], "name": device["name"], "mf": "ThingStudio"}
    if device.get("model"):
        dev["mdl"] = device["model"]
    if device.get("runtime"):
        dev["sw"] = device["runtime"]
    if device.get("area"):
        dev["sa"] = device["area"]
    cmps = {}
    for node_id, comp in components.items():
        out = dict(comp)
        out["uniq_id"] = device_id + "_" + node_id
        if comp["p"] != "button":
            out["stat_t"] = base + "/" + node_id + "/state"
        if comp["p"] in COMMANDABLE:
            out["cmd_t"] = base + "/" + node_id + "/set"
        cmps[node_id] = out
    if record and record.get("device") == device_id:
        for node_id, platform in record.get("cmps", {}).items():
            if node_id not in cmps:
                cmps[node_id] = {"p": platform}
    payload = {
        "dev": dev,
        "o": {"name": "ThingStudio", "sw": device.get("bundle") or BUNDLE_VERSION},
        "avty_t": base + "/availability",
        "cmps": cmps,
    }
    after = {"device": device_id, "cmps": {k: v["p"] for k, v in components.items()}}
    return "%s/device/%s/config" % (prefix, device_id), payload, after


DISCOVERY_LIMIT = 4096   # SPEC §8
WORST_CHIP_ID = 'f' * 16  # machine.unique_id() as hex: 6 bytes on the ESP32s, up to 8 on other boards
WORST_HOSTNAME = 'x' * 32  # MicroPython's longest hostname, for a device left unnamed (the board names it)


def _discovery_size(ctx, properties, prefix):
    """The discovery message's size as ts_ha.build_discovery makes it on the board, for this flow's valid entities
    (an entity with an error reports it itself). Worst case for what only the board knows (chip id, hostname). Not
    counted: the short stubs for entities a previous flow announced and this one dropped (SPEC §7)."""
    components = {}
    for n in ctx['flow']['nodes']:
        if n['type'].startswith('ha/') and n['type'] != 'ha/device':
            comp, err = component(n['type'], n.get('properties') or {})
            if comp is not None:
                components[str(n['id'])] = comp
    target = ctx.get('target') or {}
    info = {'name': str(properties.get('deviceName') or '') or WORST_HOSTNAME,
            'model': target.get('boardName') or target.get('label') or '',
            'runtime': '', 'area': properties.get('area') or '', 'bundle': BUNDLE_VERSION}
    topic, payload, after = build_discovery(WORST_CHIP_ID, prefix, info, components, None)
    return json_size(payload), len(components)


def _resolved(ctx, config_type, what):
    configs = [c for c in ctx['flow']['configs'] if c['type'] == config_type]
    if len(configs) != 1:
        return None, 'ha device needs exactly one %s config in the flow (it has %d)' % (what, len(configs))
    cfg = (ctx.get('referencedConfigs') or {}).get(configs[0]['id'])
    if cfg is None:
        return None, 'ha device: pick the %s in its properties' % what
    return cfg, None


def compile(ctx, properties):
    errors = []
    warnings = []
    nodes = ctx['flow']['nodes']
    devices = ha_devices(ctx)
    if len(devices) > 1:
        errors.append('a flow can have only one ha device node (this one has %d)' % len(devices))
    ha_nodes = [n for n in nodes if n['type'].startswith('ha/')]
    for n in ha_nodes:
        nid = str(n['id'])
        if not nid or len(nid) > 32 or any(ch not in ID_CHARS for ch in nid):
            errors.append('node id %r can\'t be used in MQTT topics -- use letters, digits, _ and - (at most 32)' % nid)
    if len(ha_nodes) == len(devices):
        warnings.append('ha device has no entities -- add ha sensor, ha switch and so on')

    wifi, err = _resolved(ctx, 'thingstudio/config/wifi', 'WiFi')
    if err:
        errors.append(err)
    broker, err = _resolved(ctx, 'thingstudio/config/mqtt-broker', 'MQTT broker')
    if err:
        errors.append(err)
    if errors:
        return {'errors': errors}
    security = wifi.get('security')
    if security == 'unmanaged':
        return {'errors': ['ha device: MQTT manages the WiFi connection, so the WiFi config cannot be "unmanaged"']}
    if security != 'open':
        security = 'password'
    host = str(broker.get('broker') or '').strip()
    if not host:
        return {'errors': ['ha device: the broker config has no broker hostname']}
    # As the guide's hook: any node holding the flow's broker config is an MQTT node (this one does, so it's True).
    broker_ids = [c['id'] for c in ctx['flow']['configs'] if c['type'] == 'thingstudio/config/mqtt-broker']
    defer = any(isinstance(v, str) and v in broker_ids
                for n in nodes for v in (n.get('properties') or {}).values())
    prefix = str(properties.get('prefix') or 'homeassistant').strip().strip('/') or 'homeassistant'
    size, count = _discovery_size(ctx, properties, prefix)
    if size > DISCOVERY_LIMIT:
        return {'errors': ['ha device: the discovery message would be up to %d bytes for %d entities, over the 4 KB '
                           '(%d bytes) the board can build and send (SPEC §8) -- remove entities or shorten their '
                           'names, or split them across two boards' % (size, count, DISCOVERY_LIMIT)]}
    return {'warnings': warnings, 'properties': {
        'prefix': prefix,
        'ssid': str(wifi.get('ssid') or '').strip(),
        'wifiPassword': str(wifi.get('password') or ''),
        'security': security,
        'deferToMqtt': defer,
        'broker': host,
        'port': int(broker.get('port') or 1883),
        'username': str(broker.get('username') or ''),
        'brokerPassword': str(broker.get('password') or ''),
    }}
